     1→import {
     2→  type FirebaseMessagingTypes,
     3→  getMessaging,
     4→  getToken,
     5→  onMessage,
     6→} from "@react-native-firebase/messaging";
     7→import { MatrixStorage } from "modules/matrix-client/const/matrix-storage";
     8→import { MatrixService } from "modules/matrix-client/services/matrix-service";
     9→import {
    10→  checkNotifications,
    11→  requestNotifications,
    12→  RESULTS,
    13→} from "react-native-permissions";
    14→import {
    15→  formatLocalPushNotificationMessage,
    16→  getDecryptedEventContent,
    17→} from "../util/formatLocalMessage";
    18→import { NotifeeService } from "./NotifeeService";
    19→
    20→/** Get the current user ID, works in both foreground and background */
    21→const getCurrentUserId = (): string | null => {
    22→  // Try to get from active instance first (foreground)
    23→  const instanceUserId = MatrixService.instance?.userId();
    24→  if (instanceUserId) return instanceUserId;
    25→
    26→  // Fall back to stored credentials (works in background)
    27→  const credentials = MatrixStorage.getLoginCredentials();
    28→  return credentials?.userId || null;
    29→};
    30→
    31→/**
    32→ * Ensure MatrixService is initialized for background decryption
    33→ * Uses lightweight initialization that doesn't start sync service
    34→ */
    35→const ensureServiceInitialized = async (): Promise<boolean> => {
    36→  const notificationClient = MatrixService.getNotificationClient();
    37→  if (notificationClient) return true;
    38→
    39→  // Foreground: create notification client if possible
    40→  if (MatrixService.instance) {
    41→    const client = await MatrixService.ensureNotificationClient();
    42→    return !!client;
    43→  }
    44→
    45→  // Try to restore session with lightweight background method
    46→  try {
    47→    const restored = await MatrixService.restoreSessionForBackground();
    48→    return restored;
    49→  } catch (error) {
    50→    console.error("[Push] Failed to restore session:", error);
    51→    return false;
    52→  }
    53→};
    54→
    55→const handleReceivedMessage = async (
    56→  message: FirebaseMessagingTypes.RemoteMessage,
    57→) => {
    58→  const data = message.data as unknown as NotificationData;
    59→  if (!data) return;
    60→
    61→  // Skip notifications for own messages (works in both foreground and background)
    62→  const currentUserId = getCurrentUserId();
    63→  if (currentUserId && data.sender === currentUserId) return;
    64→
    65→  const notificationId = message.messageId || `msg_${Date.now()}`;
    66→  const formattedMessage = formatLocalPushNotificationMessage(data);
    67→
    68→  if (!formattedMessage) return;
    69→
    70→  // For encrypted messages: show placeholder first, then update with decrypted content
    71→  if (data.type === "m.room.encrypted" && data.room_id && data.event_id) {
    72→    try {
    73→      // Always ensure service is initialized for encrypted messages
    74→      const initialized = await ensureServiceInitialized();
    75→      if (!initialized) return;
    76→
    77→      const roomName = MatrixService.getRoomInfo(data.room_id)?.displayName();
    78→      const decryptedContent = await getDecryptedEventContent(
    79→        data.room_id,
    80→        data.event_id,
    81→      );
    82→
    83→      if (decryptedContent) {
    84→        await NotifeeService.create({
    85→          title:
    86→            roomName ||
    87→            data.room_name ||
    88→            data.sender_display_name ||
    89→            data.sender ||
    90→            "Unknown Sender",
    91→          message: `${data.sender_display_name || data.sender}: ${decryptedContent}`,
    92→          id: notificationId,
    93→          data: { room_id: data.room_id },
    94→        });
    95→      } else {
    96→        await NotifeeService.create({
    97→          title: formattedMessage.title,
    98→          message: formattedMessage.message,
    99→          id: notificationId,
   100→          data: { room_id: formattedMessage.room_id },
   101→        });
   102→      }
   103→    } catch (error) {
   104→      console.error("[Push] Failed to decrypt:", error);
   105→    }
   106→
   107→    return;
   108→  }
   109→
   110→  // For non-encrypted messages, show directly
   111→  await NotifeeService.create({
   112→    title: formattedMessage.title,
   113→    message: formattedMessage.message,
   114→    id: notificationId,
   115→    data: { room_id: formattedMessage.room_id },
   116→  });
   117→};
   118→
   119→export const PushNotificationsService = {
   120→  getToken: async () => await getToken(getMessaging()),
   121→  /** Register the device with Matrix homeserver for push notifications
   122→   * This should be called after successful login and after push permissions */
   123→  registerPusher: async () => {
   124→    try {
   125→      const fcmToken = await getToken(getMessaging());
   126→      await MatrixService.setPusher(fcmToken);
   127→      return true;
   128→    } catch (error) {
   129→      console.error("Failed to register push notifications:", error);
   130→      throw error;
   131→    }
   132→  },
   133→  /** Unregister the device from Matrix homeserver */
   134→  unregisterPusher: async () => {
   135→    try {
   136→      const fcmToken = await getMessaging().getToken();
   137→      await MatrixService.removePusher(fcmToken);
   138→      return true;
   139→    } catch (error) {
   140→      console.error("Failed to unregister push notifications:", error);
   141→      throw error;
   142→    }
   143→  },
   144→  registerListeners: async () => {
   145→    // Foreground message handler
   146→    onMessage(getMessaging(), async (message) => {
   147→      await handleReceivedMessage(message);
   148→    });
   149→  },
   150→  /** Handle background messages - called from index.js */
   151→  handleBackgroundMessage: async (
   152→    remoteMessage: FirebaseMessagingTypes.RemoteMessage,
   153→  ) => {
   154→    await handleReceivedMessage(remoteMessage);
   155→  },
   156→  checkPermissions: async () => {
   157→    const result = await checkNotifications();
   158→    return result.status === RESULTS.GRANTED;
   159→  },
   160→  requestPermissions: async () => {
   161→    const result = await requestNotifications(["alert"]);
   162→    return result.status === RESULTS.GRANTED;
   163→  },
   164→  subscribeToTopic: async (topic: string) => {
   165→    await getMessaging().subscribeToTopic(topic);
   166→  },
   167→  unsubscribeFromTopic: async (topic: string) => {
   168→    await getMessaging().unsubscribeFromTopic(topic);
   169→  },
   170→};
